namespace BeamScheduleFormatter {
sealed class ManualSlabScheduleForm:Form {
 internal SlabScheduleRow Value;readonly TextBox mark=new TextBox{Width=160},thickness=new TextBox{Width=120};readonly DataGridView groups=new DataGridView{Dock=DockStyle.Fill,AllowUserToAddRows=false,AllowUserToDeleteRows=false,RowHeadersVisible=false,AutoSizeColumnsMode=DataGridViewAutoSizeColumnsMode.Fill,ScrollBars=ScrollBars.Both};
 internal ManualSlabScheduleForm(SlabScheduleRow initial,bool editing){Text=editing?"Edit manual slab reinforcement":"Manual slab reinforcement";ClientSize=new Size(1020,720);MinimumSize=new Size(800,640);StartPosition=FormStartPosition.CenterParent;Font=ModernUi.Body;var fields=new FlowLayoutPanel{Dock=DockStyle.Top,AutoSize=true,Padding=new Padding(12)};fields.Controls.Add(new Label{Text="Slab mark",AutoSize=true,Padding=new Padding(0,8,0,0)});fields.Controls.Add(mark);fields.Controls.Add(new Label{Text="Thickness mm",AutoSize=true,Padding=new Padding(12,8,0,0)});fields.Controls.Add(thickness);mark.ReadOnly=editing;var note=new Label{Dock=DockStyle.Top,Height=100,Padding=new Padding(14),Text="Enter only the reinforcement groups shown on the approved slab detail; leave unused groups blank. Short/long refers to bar direction. Counts are per panel (bottom) or per support strip (top). Cuts, Ld, curtailment and shared-support counts follow the existing slab calculation/configuration. This schedule applies to every takeoff row using its mark."};groups.Columns.Add("Group","Reinforcement group");groups.Columns[0].ReadOnly=true;groups.Columns[0].FillWeight=180;groups.Columns.Add("Diameter","Ø mm");var method=new DataGridViewComboBoxColumn{Name="Method",HeaderText="Input method",FlatStyle=FlatStyle.Flat};method.Items.AddRange("Spacing (mm)","Number of bars");groups.Columns.Add(method);groups.Columns.Add("Value","Spacing mm / bar count");for(int n=0;n<9;n++){var bar=initial==null?null:initial.Bars[n];groups.Rows.Add(SlabScheduleReader.Columns[n],bar==null?"":bar.Diameter.ToString(),bar!=null&&bar.ExplicitCount>0?"Number of bars":"Spacing (mm)",bar==null?"":bar.ExplicitCount>0?bar.ExplicitCount.ToString():bar.SpacingMm.ToString(CultureInfo.InvariantCulture));}if(initial!=null){mark.Text=editing?initial.Mark:"";thickness.Text=initial.Thickness.ToString(CultureInfo.InvariantCulture);}var tools=new FlowLayoutPanel{Dock=DockStyle.Bottom,AutoSize=true,Padding=new Padding(12),FlowDirection=FlowDirection.RightToLeft};var apply=new Button{Text="Apply reinforcement",AutoSize=true};var cancel=new Button{Text="Cancel",AutoSize=true,DialogResult=DialogResult.Cancel};tools.Controls.Add(apply);tools.Controls.Add(cancel);Controls.Add(groups);Controls.Add(note);Controls.Add(fields);Controls.Add(tools);CancelButton=cancel;apply.Click+=(s,e)=>{try{groups.EndEdit();Value=ManualSlabSchedule.Create(mark.Text,thickness.Text,groups.Rows.Cast<DataGridViewRow>().Select(r=>Enumerable.Range(1,3).Select(c=>Convert.ToString(r.Cells[c].Value).Trim()).ToArray()).ToArray());DialogResult=DialogResult.OK;}catch(Exception ex){MessageBox.Show(this,ex.Message,"Manual reinforcement",MessageBoxButtons.OK,MessageBoxIcon.Information);}};GridAppearance.Apply(groups);PowTheme.Apply(this);}
}
partial class SlabEstimatorForm {
 // Add a new manual schedule (owner: adding must always create a new schedule, never edit the selected row's one).
 // The schedule fills the selected takeoff row only when that row has no slab mark yet; otherwise a new row is added.
 void AddManualSchedule(IWin32Window owner){using(var dialog=new ManualSlabScheduleForm(null,false)){if(dialog.ShowDialog(owner)!=DialogResult.OK)return;var value=dialog.Value;if(schedules.ContainsKey(value.Mark))throw new Exception("Slab mark "+value.Mark+" already exists. Use a unique mark, or edit the existing schedule.");AddSource(ManualSlabSchedule.Write(value),"Manual "+value.Mark+".xml");var row=grid.CurrentRow;if(row==null||row.IsNewRow||Cell(row,1)!="")row=grid.Rows[grid.Rows.Add()];row.Cells[1].Value=value.Mark;SetSupportDefaults(row);Recalculate();}}
}
